replacements.new:
EXPORT(SceInt32, _sceKernelWaitLwCondCB, Ptr<SceKernelLwCondWork> pWork, SceUInt32 *pTimeout) {
    TRACY_FUNC(_sceKernelWaitLwCondCB, pWork, pTimeout);
#if defined(__SWITCH__) && defined(VITA3K_SWITCH_TRACELAB)
    switch_validation::epoch::CallbackPrefixScope callback_prefix(
        switch_validation::epoch::HostLease::callback_context());
    const auto callback_thread = emuenv.kernel.get_thread(thread_id);
    // A recursive or missing-thread path is not a completed empty scan.
    const bool full_callback_scan = callback_thread && !callback_thread->is_processing_callbacks;
    const uint32_t callbacks_processed = process_callbacks(emuenv.kernel, thread_id);
    callback_prefix.finish(full_callback_scan, callbacks_processed);
#else
    process_callbacks(emuenv.kernel, thread_id);
#endif
    const auto cond_id = pWork.get(emuenv.mem)->uid;
    return condvar_wait(emuenv.kernel, emuenv.mem, export_name, thread_id, cond_id, pTimeout, SyncWeight::Light);
}
